namespace FsAnalyser.Core.Tests;

/// <summary>
/// Review repro (SL-003): W-003 on a real share where the hook pressed Stop and the app reached no stopped ending before
/// the 600 s wait killed it. The contract says FAILED when the app timed out, so the record's verdict is 'failed' and the
/// case records a failure. Test-W003Real is loaded from the script's parse; the launch is stubbed.
/// </summary>
public class W003RealStopNoEndingReproTests
{
    [Fact]
    public async Task ARealShareRunWhoseStopReachesNoEndingIsFailed()
    {
        string[] functions = ["Test-W003Real", "Read-ActedLine", "Get-StopToEndingMs", "Get-CutFolderRows", "Get-ShareVerdict", "New-ShareRecord", "Get-RecordString", "Get-RecordByCode", "Get-ProofRecordPath", "Show", "Check", "CheckEqual", "Inconclusive"];
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + string.Concat(functions.Select(WindowCasesHelperTests.Load)) + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Repo = Join-Path ([System.IO.Path]::GetTempPath()) ('w003-real-' + [guid]::NewGuid().ToString('N'))
            [void][System.IO.Directory]::CreateDirectory($Repo)
            $Root = $Repo
            $Network = 'home'
            $Link = 'wifi-off'
            $HookDll = 'unused.dll'
            $global:saved = $null
            function Read-Host { '' }
            function New-CaseFolder { $f = Join-Path $Repo ('case-' + [guid]::NewGuid().ToString('N')); [void][System.IO.Directory]::CreateDirectory($f); $f }
            function Remove-CaseFolder($folder) { }
            function Read-RowsDump($log) { [pscustomobject]@{ Rows = @(); NotScanned = @(); Closing = $null } }
            function Save-ProofRecord($file, $record, $reasons) { $global:saved = $record }
            function Invoke-WithHook($mode, $hookDll, $action, $armed) { [pscustomobject]@{ Result = [pscustomobject]@{ Exit = 'TIMEOUT'; Answer = 'cut' }; Log = @('loaded mode=stop pid=1', 'armed ms=30000', 'acted mode=stop enabled=True visible=True ms=32000 sincearmed=2000') } }
            try { [void](Test-W003Real) } catch { 'threw: ' + $_.Exception.Message }
            Remove-Item -LiteralPath $Repo -Recurse -Force
            "result verdict=$($global:saved.verdict) failed=$($script:Failures.Count -gt 0)"
            """);

        Assert.Contains("result verdict=failed failed=True", output);
    }
}

namespace FsAnalyser.Core.Tests;

/// <summary>
/// Review repro (SL-003): a W-001 -Stopped attempt where the hook pressed Stop while folders were being listed and the app
/// then timed out (killed, no report) must make the stopped part 'failed', not be retried into a 'held' one. The
/// launch is stubbed; Invoke-W001StoppedRun is loaded from the script's parse.
/// </summary>
public class W001StoppedTimeoutReproTests
{
    [Fact]
    public async Task AStoppedAttemptThatTimedOutAfterStopFailsTheStoppedPart()
    {
        string[] functions = ["Invoke-W001StoppedRun", "Read-ActedLine", "Test-StoppedPartial", "Compare-StoppedRows", "Get-StoppedVerdict", "New-StoppedPart", "Get-RecordString", "Show", "Check", "CheckEqual", "Inconclusive"];
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + string.Concat(functions.Select(WindowCasesHelperTests.Load)) + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Root = 'X:\'
            $global:calls = 0
            function Invoke-HookedRun($mode, $root, $report, $variables, $timeoutSec) {
                $global:calls++
                if ($global:calls -eq 1) { return [pscustomobject]@{ Exit = 'TIMEOUT'; Report = $null; Text = $null; Log = @('acted mode=stop atfolders=100 folders=120 sized=- current=X:\a ms=900 utc=2026-11-17T19:05:45Z') } }
                [pscustomobject]@{ Exit = '0'; Report = [pscustomobject]@{ core = [pscustomobject]@{ status = 'Cancelled'; folders = 80; unreadable = 0 }; outcome = 'cancelled' }; Text = '{}'; Log = @('acted mode=stop atfolders=50 folders=60 sized=- current=X:\a ms=900 utc=2026-11-17T19:05:45Z') }
            }
            function Read-RowsDump($log) { [pscustomobject]@{ Rows = @(); NotScanned = @(); Closing = [pscustomobject]@{ count = 0; elevated = $false } } }
            function CheckPanelAgrees { }
            function Save-ProofRecord($file, $record, $reasons) { }
            $record = [ordered]@{}
            $finished = [pscustomobject]@{ Report = [pscustomobject]@{ core = [pscustomobject]@{ folders = 200 } } }
            try { [void](Invoke-W001StoppedRun ([System.IO.Path]::GetTempPath()) $finished @() ([DateTime]::UtcNow) $record 'unused.json' @()) } catch { 'threw: ' + $_.Exception.Message }
            "result stopped verdict=$($record['stopped'].verdict)"
            """);

        Assert.Contains("result stopped verdict=failed", output);
    }
}

namespace FsAnalyser.Core.Tests;

/// <summary>
/// Review repro (SL-003, O-003): W-003 on a real share whose marker the hook refused after its 60 s deadline is
/// INCONCLUSIVE, even when the wait then timed out: the case reports it as inconclusive and records no failure.
/// </summary>
public class W003MarkerRefusedReproTests
{
    [Fact]
    public async Task ARefusedMarkerEndsTheRealShareRunInconclusive()
    {
        string[] functions = ["Test-W003Real", "Read-ActedLine", "Get-StopToEndingMs", "Get-CutFolderRows", "Get-ShareVerdict", "New-ShareRecord", "Get-RecordString", "Get-RecordByCode", "Get-ProofRecordPath", "Show", "Check", "CheckEqual", "Inconclusive"];
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + string.Concat(functions.Select(WindowCasesHelperTests.Load)) + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Repo = Join-Path ([System.IO.Path]::GetTempPath()) ('w003-refused-' + [guid]::NewGuid().ToString('N'))
            [void][System.IO.Directory]::CreateDirectory($Repo)
            $Root = $Repo
            $Network = 'home'
            $Link = 'wifi-off'
            $HookDll = 'unused.dll'
            $global:saved = $null
            function Read-Host { '' }
            function New-CaseFolder { $f = Join-Path $Repo ('case-' + [guid]::NewGuid().ToString('N')); [void][System.IO.Directory]::CreateDirectory($f); $f }
            function Remove-CaseFolder($folder) { }
            function Read-RowsDump($log) { [pscustomobject]@{ Rows = @(); NotScanned = @(); Closing = $null } }
            function Save-ProofRecord($file, $record, $reasons) { $global:saved = $record }
            function Invoke-WithHook($mode, $hookDll, $action, $armed) { [pscustomobject]@{ Result = [pscustomobject]@{ Exit = 'TIMEOUT'; Answer = 'cut' }; Log = @('loaded mode=stop pid=1', "refused mode=stop reason=the rig's marker C:\case\cut.armed did not appear within 60 s, so the stall never armed") } }
            try { [void](Test-W003Real) } catch { 'threw: ' + $_.Exception.Message }
            Remove-Item -LiteralPath $Repo -Recurse -Force
            "result verdict=$($global:saved.verdict) failures=$($script:Failures.Count) inconclusive=$($script:Inconclusive.Count -gt 0)"
            """);

        Assert.Contains("result verdict=inconclusive failures=0 inconclusive=True", output);
    }
}

namespace FsAnalyser.Core.Tests;

/// <summary>
/// Review repro (SL-003): W-001 -Stopped makes its stopped run only after a finished run that ended Completed; a finished
/// run that ended RootUnreadable starts no second scan. Test-W001 is loaded from the script's parse, the launch stubbed.
/// </summary>
public class W001StoppedAfterIncompleteReproTests
{
    [Fact]
    public async Task NoStoppedRunFollowsAFinishedRunThatDidNotComplete()
    {
        string[] functions = ["Test-W001", "Initialize-SeamWin32", "Get-W001RootShape", "Get-ProofRecordPath", "Test-KeptStoppedPart", "Get-WholeDriveReportGaps", "Get-LeakCount", "Get-ReasonCodeMismatches", "Get-W001Verdict", "Get-RecordString", "Get-HeaderCount", "Get-RecordByCode", "Get-CoverageRecord", "Get-CountsOnly", "Test-CountsOnlyKept", "Get-RoundedOrNull", "Show", "Check", "CheckEqual", "Inconclusive"];
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + string.Concat(functions.Select(WindowCasesHelperTests.Load)) + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Repo = Join-Path ([System.IO.Path]::GetTempPath()) ('w001-incomplete-' + [guid]::NewGuid().ToString('N'))
            [void][System.IO.Directory]::CreateDirectory($Repo)
            $Root = $Repo
            $Stopped = $true
            $Force = $false
            $global:stoppedStarted = $false
            function Test-Elevated { $false }
            function New-CaseFolder { $f = Join-Path $Repo ('case-' + [guid]::NewGuid().ToString('N')); [void][System.IO.Directory]::CreateDirectory($f); $f }
            function Remove-CaseFolder($folder) { }
            function Get-CheckerControls($case) { [pscustomobject]@{ Openable = $true; Denied = $true; RefusedThenListed = $true; Folders = @() } }
            function Invoke-HookedRun($mode, $root, $report, $variables, $timeoutSec) {
                [pscustomobject]@{ Exit = '0'; Report = [pscustomobject]@{ core = [pscustomobject]@{ status = 'RootUnreadable'; folders = 0; files = 0; unreadable = 0; elapsedMs = 5 }; outcome = 'root-unreadable'; workarounds = @(); window = [pscustomobject]@{} }; Text = '{}'; Log = @() }
            }
            function Read-RowsDump($log) { [pscustomobject]@{ Rows = @(); NotScanned = @(); Closing = [pscustomobject]@{ count = 0; elevated = $false } } }
            function CheckPanelAgrees { }
            function Save-ProofRecord($file, $record, $reasons) { }
            function Invoke-W001StoppedRun { $global:stoppedStarted = $true }
            try { [void](Test-W001) } catch { 'threw: ' + $_.Exception.Message }
            Remove-Item -LiteralPath $Repo -Recurse -Force
            "result stopped run started=$global:stoppedStarted"
            """);

        Assert.Contains("result stopped run started=False", output);
    }
}

namespace FsAnalyser.Core.Tests;

/// <summary>
/// Review repro (SL-003, decision n1): W-002 on a scan that did not end Completed (here Refused) is INCONCLUSIVE, not a
/// failure: it read nothing, so nothing is shown either way. Test-W002 is loaded from the script's parse; the app is stubbed
/// and the root is a plain temp folder, so no sync root is registered.
/// </summary>
public class W002NotCompletedReproTests
{
    [Fact]
    public async Task AScanThatWasRefusedEndsW002InconclusiveNotFailed()
    {
        string[] functions = ["Test-W002", "Initialize-SeamWin32", "Get-HydrationTally", "Get-HydrationVerdict", "New-HydrationRecord", "Get-DataFetches", "Get-RecordString", "Get-ProofRecordPath", "Show", "Check", "CheckEqual", "Inconclusive"];
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + string.Concat(functions.Select(WindowCasesHelperTests.Load)) + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Repo = Join-Path ([System.IO.Path]::GetTempPath()) ('w002-refused-' + [guid]::NewGuid().ToString('N'))
            $Root = Join-Path $Repo 'root'
            [void][System.IO.Directory]::CreateDirectory($Root)
            [System.IO.File]::WriteAllText((Join-Path $Root 'a.txt'), 'x')
            $global:saved = $null
            function Read-Host { '' }
            function New-CaseFolder { $global:caseFolder = Join-Path $Repo ('case-' + [guid]::NewGuid().ToString('N')); [void][System.IO.Directory]::CreateDirectory($global:caseFolder); $global:caseFolder }
            function Remove-CaseFolder($folder) { }
            function Format-AppArgument($value) { [string]$value }
            function Start-App($arguments) {
                [System.IO.File]::WriteAllText((Join-Path $global:caseFolder 'report.json'), '{"core":{"status":"Refused","unreadable":0},"outcome":"refused"}')
                [pscustomobject]@{ Id = 4242 }
            }
            function Wait-App($process, $timeoutSec) { '0' }
            function Save-ProofRecord($file, $record, $reasons) { $global:saved = $record }
            try { [void](Test-W002) } catch { 'threw: ' + $_.Exception.Message }
            Remove-Item -LiteralPath $Repo -Recurse -Force
            "result verdict=$($global:saved.verdict) failures=$($script:Failures.Count) inconclusive=$($script:Inconclusive.Count -gt 0)"
            """);

        Assert.Contains("result verdict=inconclusive failures=0 inconclusive=True", output);
    }
}

namespace FsAnalyser.Core.Tests;

/// <summary>
/// W-001 -Stopped's attempts: an attempt whose app never reached an ending (TIMEOUT after Stop was pressed) is a Stop that
/// hung, which the design fails; a later partial attempt must not turn the run into 'held'.
/// </summary>
public class W001StoppedRetryTests
{
    [Fact]
    public async Task AStoppedAttemptThatTimedOutIsNotLaunderedByALaterAttempt()
    {
        string loaded = string.Concat(new[] { "Invoke-W001StoppedRun", "Read-ActedLine", "Test-StoppedPartial", "Compare-StoppedRows", "Get-StoppedVerdict",
            "New-StoppedPart", "Get-RecordString", "Read-RowsDump", "Read-HookJson", "Check", "CheckEqual", "Show", "Inconclusive", "Save-ProofRecord",
            "Write-W001Record" }.Select(WindowCasesHelperTests.Load));
        string output = await WindowCasesHelperTests.Pwsh(WindowCasesHelperTests.ParseScript() + loaded + """
            $script:Failures = [System.Collections.Generic.List[string]]::new()
            $script:Inconclusive = [System.Collections.Generic.List[string]]::new()
            $Root = 'X:\'
            $script:calls = 0
            function Invoke-HookedRun($mode, $root, $report, $variables, $timeoutSec) {
                $script:calls++
                if ($script:calls -eq 1) {
                    return [pscustomobject]@{ Exit = 'TIMEOUT'; Report = $null; Text = $null; Log = @('acted mode=stop atfolders=50 folders=60 sized=- current=X:\b ms=900 utc=2026-11-18T00:00:00Z') }
                }
                $scan = [pscustomobject]@{ core = [pscustomobject]@{ status = 'Cancelled'; folders = 30; unreadable = 0 }; outcome = 'cancelled' }
                [pscustomobject]@{ Exit = '0'; Report = $scan; Text = '{}'; Log = @('acted mode=stop atfolders=25 folders=30 sized=- current=X:\c ms=800 utc=2026-11-18T00:00:01Z', '{"event":"rows","count":0,"elevated":false,"stopUtc":"2026-11-18T00:00:01Z"}') }
            }
            function CheckPanelAgrees { }
            $finished = [pscustomobject]@{ Report = [pscustomobject]@{ core = [pscustomobject]@{ folders = 100 } } }
            $record = [ordered]@{ verdict = 'held' }
            $file = Join-Path ([IO.Path]::GetTempPath()) ('w001-stopped-' + [guid]::NewGuid().ToString('N') + '.json')
            try { Invoke-W001StoppedRun 'unused-case' $finished @() ([DateTime]::UtcNow.AddHours(-1)) $record $file @() } catch { "threw: $($_.Exception.Message)" }
            "result verdict=$($record['stopped'].verdict)"
            if (Test-Path -LiteralPath $file) { Remove-Item -LiteralPath $file }
            """);

        Assert.Contains("result verdict=failed", output);
    }
}

